from taf.collectors.docker.factory import DockerCollectorFactorySelector
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class docker(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_docker_collector(self,
                                name,
                                pod_name,
                                namespace,
                                executor,
                                container=None,
                                sudo_password=None,
                                target_file_name=None):
        """
            Create docker Collector from given configuration

            :param str name: name of collector
            :param str namespace: name of namespace, it will use default if not set
            :param str pod_name: name of pod
            :param dict executor: setup info host, user, password,in dict format
            :param str container: (optional) single container name, default: None
            :param str sudo_password: (optional) sudo password for some command need root permission
                    default value: None
            :param str target_file_name: (optional) file_name.tgz format, its part of the path under which syslog file
                                            stored locally during collect_collectors
                                         default value: None
            :return: DockerCollector

.. code-block:: robotframework

            *** Settings ***
            Library    taf.collectors.docker    WITH NAME    dockerlog
            Library    taf.collectors.core    WITH NAME    core
            *** Test Cases ***
            test_syslog
                ${proxy}= Create Dictionary
                ...  host=10.68.92.10
                ...  user=cranuser11
                ...  password=systeM!23 master
                ${executor}= Create Dictionary
                ...  host=192.168.10.25
                ...  user=cranuser11
                ...  password=systeM!23
                ...  proxy=${proxy}
                dockerlog.create_docker_collector
                ...    name=syslog
                ...    namespace=cran1
                ...    pod_name=kt-aic-vdu-oamcp-deployment-0
                ...    container=cprt
                ...    executor=${executor}
                ...    sudo_password='systeM!23'
                core.setup_collectors    names=syslog
                core.collect_collectors    names=syslog    target_dir=/home/ute/syslog/
                core.teardown_collectors    names=syslog
        """
        configuration = dict(name=name, executor=executor,
                             namespace=namespace, pod_name=pod_name)

        if container is not None:
            configuration["container"] = container
        if target_file_name is not None:
            configuration["target_file_name"] = target_file_name
        if sudo_password is not None:
            configuration["sudo_password"] = sudo_password
        docker_collector = DockerCollectorFactorySelector().create(configuration=configuration, existing_arguments={})
        logger.info("Docker Collector created successfully")
        logger.debug("setting alias {name!r} for {collector!r}".format(
            name=name,
            collector=docker_collector))
        self.set_alias(name, docker_collector)
